package com.hbm.machine.gascentrifuge;
import com.hbm.api.machine.MachineView;import com.hbm.energy.*;import com.hbm.fluid.*;import com.hbm.fluid.network.*;import com.hbm.item.battery.*;import com.hbm.item.fluid.FluidIdentifier;import com.hbm.multiblock.*;import com.hbm.machine.gascentrifuge.GasCentrifugeRecipes.PseudoFluidType;import java.util.*;import java.util.function.Consumer;import net.minecraft.core.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;
/** X5846 actual staged gaseous enrichment, including ten-tick inter-machine cascading. */
public final class GasCentrifugeBlockEntity extends BlockEntity implements WorldlyContainer,MenuProvider,NamedMultiblock,EnergyReceiver,SidedEnergyConnector,StandardFluidReceiver,MachineView,MuffledMachine {
 public static final int MAX_POWER=100000,PROCESSING_SPEED=150;public static Consumer<GasCentrifugeBlockEntity> CLIENT_TICK=ignored->{},CLIENT_REMOVED=ignored->{};private final NonNullList<ItemStack> inventory=NonNullList.withSize(7,ItemStack.EMPTY);public long power;public int progress;public boolean isProgressing,muffled,tilted;public final FluidTank tank=new FluidTank(HbmFluids.UF6,2000);public final PseudoFluidTank inputTank=new PseudoFluidTank(PseudoFluidType.NUF6,8000),outputTank=new PseudoFluidTank(PseudoFluidType.LEUF6,8000);private PowerNode node;private FluidPorts fluidPorts;private Component customName;
 public GasCentrifugeBlockEntity(BlockPos pos,BlockState state){super(GasCentrifugeContent.ENTITY.get(),pos,state);}@Override public boolean isValidBlockState(BlockState state){return super.isValidBlockState(state)&&DummyableBlock.isCore(state);}@Override public Component getDisplayName(){return customName==null?Component.translatable("container.gasCentrifuge"):customName;}@Override public void setCustomName(Component name){customName=name;setChanged();}@Override public AbstractContainerMenu createMenu(int id,Inventory player,Player opener){return new GasCentrifugeMenu(id,player,this,worldPosition);}
 public static void tick(Level level,BlockPos pos,BlockState state,GasCentrifugeBlockEntity machine){if(level instanceof ServerLevel server)machine.serverTick(server);else CLIENT_TICK.accept(machine);}
 private void serverTick(ServerLevel server){ensurePorts(server);chargeFromItem();setTankType();if(GasCentrifugeRecipes.convertible(inputTank.type))attemptConversion();if(canEnrich()){isProgressing=true;progress++;power-=fast()?300:200;if(power<0){power=0;progress=0;}if(progress>=getProcessingSpeed())enrich();}else{isProgressing=false;progress=0;}if(server.getGameTime()%10==0){var target=worldPosition.relative(DummyableBlock.facing(getBlockState()).getOpposite());if(!attemptTransfer(server.getBlockEntity(target))&&inputTank.type==PseudoFluidType.LEUF6){var products=List.of(GasCentrifugeRecipes.item("nugget_uranium_fuel",6),GasCentrifugeRecipes.item("fluorite",1));if(outputTank.fluid>=600&&hasSpace(products)){outputTank.fluid-=600;for(var stack:products)add(inventory,stack);}}}setChanged();var packet=getUpdatePacket();try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<2500)player.connection.send(packet);dispatchScope.commit();}}
 public boolean fast(){return inventory.get(6).getItem()==GasCentrifugeContent.SPEED.get();}public int getProcessingSpeed(){return fast()?PROCESSING_SPEED-70:PROCESSING_SPEED;}
 private boolean canEnrich(){if(power<=0||inputTank.fluid<inputTank.type.fluidConsumed||outputTank.fluid+inputTank.type.fluidProduced>outputTank.maxFluid)return false;if(inputTank.type.highSpeed&&!fast())return false;var products=inputTank.type.outputs();return !products.isEmpty()&&hasSpace(products);}
 private void enrich(){var products=inputTank.type.outputs();progress=0;inputTank.fluid-=inputTank.type.fluidConsumed;outputTank.fluid+=inputTank.type.fluidProduced;for(var stack:products)add(inventory,stack);}
 private void attemptConversion(){if(inputTank.fluid<inputTank.maxFluid&&tank.getFill()>0){int fill=Math.min(inputTank.maxFluid-inputTank.fluid,tank.getFill());tank.setFill(tank.getFill()-fill);inputTank.fluid+=fill;}}
 private boolean attemptTransfer(BlockEntity tile){if(tile instanceof GasCentrifugeBlockEntity cent&&cent.tank.getTankType()==tank.getTankType()){if(cent.inputTank.type!=outputTank.type&&outputTank.type!=PseudoFluidType.NONE){cent.inputTank.setType(outputTank.type);cent.outputTank.setType(outputTank.type.outputType());}if(cent.inputTank.fluid<cent.inputTank.maxFluid&&outputTank.fluid>0){int fill=Math.min(cent.inputTank.maxFluid-cent.inputTank.fluid,outputTank.fluid);outputTank.fluid-=fill;cent.inputTank.fluid+=fill;cent.setChanged();}return true;}return false;}
 private void setTankType(){var stack=inventory.get(5);if(stack.getItem() instanceof FluidIdentifier identifier){var type=identifier.getType(level,worldPosition,stack);if(tank.getTankType()!=type){var pseudo=GasCentrifugeRecipes.conversion(type);if(pseudo!=null){inputTank.setType(pseudo);outputTank.setType(pseudo.outputType());tank.setTankType(type);}}}}
 private boolean hasSpace(List<ItemStack> products){var copy=NonNullList.withSize(4,ItemStack.EMPTY);for(int i=0;i<4;i++)copy.set(i,inventory.get(i).copy());for(var stack:products)if(!add(copy,stack.copy()).isEmpty())return false;return true;}
 /** Original InventoryUtil merges all matching stacks before choosing its first empty slot. */
 private static ItemStack add(List<ItemStack> slots,ItemStack stack){for(int i=0;i<4;i++){var present=slots.get(i);if(!present.isEmpty()&&ItemStack.isSameItemSameComponents(present,stack)){int amount=Math.min(stack.getCount(),present.getMaxStackSize()-present.getCount());if(amount>0){present.grow(amount);stack.shrink(amount);if(stack.isEmpty())return ItemStack.EMPTY;}}}for(int i=0;i<4;i++)if(slots.get(i).isEmpty()){slots.set(i,stack);return ItemStack.EMPTY;}return stack;}
 private void chargeFromItem(){var stack=inventory.get(4);if(stack.getItem() instanceof CreativeBatteryItem){power=MAX_POWER;return;}if(stack.getItem() instanceof HbmBattery battery){long amount=Math.min(Math.min(MAX_POWER-power,battery.getDischargeRate(stack)),battery.getCharge(stack));battery.dischargeBattery(stack,amount);power+=amount;}}
 private void ensurePorts(ServerLevel server){if(node==null||node.isExpired()){node=new PowerNode(worldPosition);node.setConnections(Arrays.stream(Direction.values()).map(side->new NodeConnection(worldPosition.relative(side),side)).toArray(NodeConnection[]::new));node.addReceiver(this);HbmEnergy.nodespace(server).createNode(node);}if(fluidPorts==null)fluidPorts=new FluidPorts(worldPosition);fluidPorts.update(server,this);}
 private void disconnect(){if(level instanceof ServerLevel server){if(node!=null)HbmEnergy.nodespace(server).destroyNode(node);if(fluidPorts!=null)fluidPorts.remove(server);}node=null;fluidPorts=null;}@Override public void onChunkUnloaded(){disconnect();if(level!=null&&level.isClientSide)CLIENT_REMOVED.accept(this);super.onChunkUnloaded();}@Override public void setRemoved(){disconnect();if(level!=null&&level.isClientSide)CLIENT_REMOVED.accept(this);super.setRemoved();}@Override public boolean isLoaded(){return level!=null&&!isRemoved()&&level.hasChunkAt(worldPosition);}@Override public boolean canConnect(Direction side){return side!=null;}@Override public boolean canConnect(HbmFluidType type,Direction side){return side!=null;}@Override public long getPower(){return power;}@Override public long getMaxPower(){return MAX_POWER;}@Override public void setPower(long value){power=Math.max(0,Math.min(MAX_POWER,value));setChanged();}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{tank};}@Override public FluidTank[] getAllTanks(){return getReceivingTanks();}@Override public long transferFluid(HbmFluidType type,int pressure,long amount){long rejected=StandardFluidReceiver.super.transferFluid(type,pressure,amount);if(rejected!=amount)setChanged();return rejected;}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}public float volume(float value){return muffled?value*.1F:value;}@Override public long energyStored(){return power;}@Override public long energyCapacity(){return MAX_POWER;}@Override public List<TankView> tanks(){return List.of(new TankView(tank.getTankType(),tank.getFill(),tank.getMaxFill()),new TankView(inputTank.type.nameKey(),inputTank.fluid,inputTank.maxFluid),new TankView(outputTank.type.nameKey(),outputTank.fluid,outputTank.maxFluid));}@Override public List<ProgressView> progressBars(){return progress>0?List.of(new ProgressView("jade.hbm.processing",progress,getProcessingSpeed(),0x71C78B)):List.of();}
 private void writeState(CompoundTag tag){tag.putLong("power",power);tag.putShort("progress",(short)progress);tank.writeToNBT(tag,"tank");inputTank.write(tag,"inputTank");outputTank.write(tag,"outputTank");tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);}private void readState(CompoundTag tag){power=tag.getLong("power");progress=tag.getShort("progress");tank.readFromNBT(tag,"tank");inputTank.read(tag,"inputTank");outputTank.read(tag,"outputTank");muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);ContainerHelper.saveAllItems(tag,inventory,lookup);writeState(tag);if(customName!=null)tag.putString("CustomName",Component.Serializer.toJson(customName,lookup));}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);ContainerHelper.loadAllItems(tag,inventory,lookup);readState(tag);if(tag.contains("CustomName"))customName=Component.Serializer.fromJson(tag.getString("CustomName"),lookup);}@Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();writeState(tag);tag.putBoolean("isProgressing",isProgressing);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){readState(tag);isProgressing=tag.getBoolean("isProgressing");}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
 @Override public int getContainerSize(){return 7;}@Override public boolean isEmpty(){return inventory.stream().allMatch(ItemStack::isEmpty);}@Override public ItemStack getItem(int slot){return inventory.get(slot);}@Override public ItemStack removeItem(int slot,int count){var result=ContainerHelper.removeItem(inventory,slot,count);if(!result.isEmpty())setChanged();return result;}@Override public ItemStack removeItemNoUpdate(int slot){return ContainerHelper.takeItem(inventory,slot);}@Override public void setItem(int slot,ItemStack stack){inventory.set(slot,stack);if(stack.getCount()>64)stack.setCount(64);setChanged();}@Override public void clearContent(){inventory.clear();setChanged();}@Override public boolean stillValid(Player player){return com.hbm.multiblock.SourceMachineMenuRange.isValid(this,player);}@Override public boolean canPlaceItem(int slot,ItemStack stack){return false;}@Override public int[] getSlotsForFace(Direction side){return new int[]{0,1,2,3};}@Override public boolean canPlaceItemThroughFace(int slot,ItemStack stack,Direction side){return false;}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return slot<4;}
 public static final class PseudoFluidTank {public PseudoFluidType type;public int fluid,maxFluid;public PseudoFluidTank(PseudoFluidType type,int maxFluid){this.type=type;this.maxFluid=maxFluid;}public void setType(PseudoFluidType next){if(type==next)return;type=next==null?PseudoFluidType.NONE:next;fluid=0;}public void write(CompoundTag tag,String key){tag.putInt(key,fluid);tag.putInt(key+"_max",maxFluid);tag.putString(key+"_type",type.name());}public void read(CompoundTag tag,String key){fluid=tag.getInt(key);if(tag.getInt(key+"_max")>0)maxFluid=tag.getInt(key+"_max");type=PseudoFluidType.byName(tag.getString(key+"_type"));}}
}
